const results = [];
for (const item of $input.all()) {
  const sourceUrl = item.json.source_url;
  let sourceType = '';
  let videoId = '';
  let aspectRatio = '16:9';

  if (sourceUrl.includes('youtube.com') || sourceUrl.includes('youtu.be')) {
    sourceType = 'youtube';
    if (sourceUrl.includes('v=')) videoId = sourceUrl.split('v=')[1].split('&')[0];
    else if (sourceUrl.includes('youtu.be/')) videoId = sourceUrl.split('youtu.be/')[1].split('?')[0];
    else if (sourceUrl.includes('/shorts/')) videoId = sourceUrl.split('/shorts/')[1].split('?')[0];
  } else if (sourceUrl.includes('instagram.com')) {
    sourceType = 'instagram';
    aspectRatio = '9:16';
    const m = sourceUrl.match(/instagram\.com\/(?:reel|reels|p)\/([A-Za-z0-9_-]+)/);
    if (m) videoId = m[1];
  }

  if (!videoId || !sourceType) {
    results.push({ json: { source_url: sourceUrl, source_type: 'unknown', video_id: '', title: 'ERROR: Unsupported URL', aspect_ratio: '16:9' } });
    continue;
  }

  // Sanitize video_id for use in file paths
  const safeId = videoId.replace(/[^A-Za-z0-9_-]/g, '_');

  let title = safeId;
  try {
    if (sourceType === 'youtube') {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.youtube.com/oembed?format=json&url=https://www.youtube.com/watch?v=' + videoId });
      const data = typeof r === 'string' ? JSON.parse(r) : r;
      title = data.title || safeId;
    }
  } catch(e) { title = safeId; }

  results.push({ json: { source_url: sourceUrl, source_type: sourceType, video_id: safeId, title, aspect_ratio: aspectRatio } });
}
return results;

const FFMPEG = 'C:\\Users\\user\\AppData\\Local\\Microsoft\\WinGet\\Packages\\Gyan.FFmpeg_Microsoft.Winget.Source_8wekyb3d8bbwe\\ffmpeg-8.1.1-full_build\\bin\\ffmpeg.exe';
const TEMP = 'C:\\Users\\user\\Desktop\\AI\\vid-generator\\temp';
const item = $input.first().json;
const videoId = item.video_id;
const sourceUrl = item.source_url;

// Use video_id as output filename so we know exactly where the file is
const ytdlpCmd = `yt-dlp -o "${TEMP}\\${videoId}.%(ext)s" --merge-output-format mp4 --no-playlist "${sourceUrl}"`;
const ffmpegCmd = `"${FFMPEG}" -i "${TEMP}\\${videoId}.mp4" -vf "fps=1,scale=640:-1" -q:v 3 -vframes 30 "${TEMP}\\${videoId}_frame_%03d.jpg" -y`;
const mkdirCmd = `cmd /c if not exist "${TEMP}" mkdir "${TEMP}" && echo created`;

return [{ json: {
  source_url: item.source_url,
  source_type: item.source_type,
  video_id: videoId,
  title: item.title,
  aspect_ratio: item.aspect_ratio,
  ytdlp_cmd: ytdlpCmd,
  ffmpeg_cmd: ffmpegCmd,
  mkdir_cmd: mkdirCmd,
  temp_dir: TEMP,
  ffmpeg_path: FFMPEG
} }];

const fs = require('fs');
const path = require('path');

const cmdData = $('Build Commands').first().json;
const videoId = cmdData.video_id;
const tempDir = cmdData.temp_dir;
const prefix = videoId + '_frame_';

let frames = [];
try {
  const files = fs.readdirSync(tempDir)
    .filter(f => f.startsWith(prefix) && f.endsWith('.jpg'))
    .sort();

  // Sample evenly — up to 15 frames to keep Gemini token cost low
  const maxFrames = 15;
  let selected;
  if (files.length <= maxFrames) {
    selected = files;
  } else {
    selected = [];
    const step = (files.length - 1) / (maxFrames - 1);
    for (let i = 0; i < maxFrames; i++) {
      selected.push(files[Math.round(i * step)]);
    }
  }

  frames = selected.map(f => {
    const buf = fs.readFileSync(path.join(tempDir, f));
    return buf.toString('base64');
  });
} catch(e) {
  frames = [];
}

return [{ json: {
  source_url: cmdData.source_url,
  source_type: cmdData.source_type,
  video_id: videoId,
  title: cmdData.title,
  aspect_ratio: cmdData.aspect_ratio,
  frame_images: frames,
  frame_count: frames.length,
  temp_dir: tempDir
} }];

const item = $input.first().json;
const frames = item.frame_images || [];
const title = item.title || '';
const aspectRatio = item.aspect_ratio || '16:9';

const parts = [];

// Add each frame as inlineData
frames.forEach(frameBase64 => {
  if (frameBase64) {
    parts.push({ inlineData: { mimeType: 'image/jpeg', data: frameBase64 } });
  }
});

const frameNote = frames.length > 0
  ? `These are ${frames.length} frames extracted at 1 frame per second from the actual video, showing the complete visual content.`
  : 'No video frames available — analyze based on title only.';

parts.push({
  text: `Title: ${title}\nAspect Ratio: ${aspectRatio}\n\n${frameNote}\n\nAnalyze ALL provided frames to understand the complete video: scene progression, character actions, camera movements, visual style, color grading, and narrative arc. Produce the cinematographic analysis as instructed.`
});

const systemText = `You are an expert cinematographer and visual analyst. You receive multiple video frames (1 frame per second) showing the actual video content. Analyze ALL frames carefully to understand the complete video.\n\nOutput ONLY a valid JSON object, no markdown fences, no prose:\n{\n  "subject": "primary subject(s), their appearance (age, clothing, hair color, ethnicity as visible), and evolving actions across all frames",\n  "setting": "exact location, time of day, background elements, atmosphere",\n  "composition": "shot types used (wide/medium/close-up/extreme-close), angles, framing",\n  "camera_movement": "specific movements: static/pan/tilt/dolly/handheld/tracking — be precise",\n  "lighting": "key light direction, color temperature in Kelvin, shadow quality, practical vs artificial",\n  "color_palette": "dominant hues with approximate hex codes, grading style (teal-orange, desaturated, warm, etc.)",\n  "texture_and_materials": "fabric, skin, surfaces, reflections — tactile details visible in frames",\n  "scene_progression": "how the action evolves from first to last frame, key transitions and beats",\n  "key_moments": ["moment 1", "moment 2", "moment 3", "moment 4", "moment 5"],\n  "mood": "emotional register and energy level the visuals convey",\n  "recommended_segments": 4\n}\n\nSet recommended_segments to 4 (four 8-second Veo clips = ~32 seconds of video). Be concrete about what you SEE in the frames.`;

const body = {
  contents: [{ role: 'user', parts: parts }],
  systemInstruction: { parts: [{ text: systemText }] },
  generationConfig: { temperature: 0.3 }
};

return [{ json: {
  source_url: item.source_url,
  source_type: item.source_type,
  video_id: item.video_id,
  title: title,
  aspect_ratio: aspectRatio,
  frame_count: frames.length,
  gemini_body: JSON.stringify(body)
} }];

const srcData = $('Build Analysis Request').first().json;
const response = $input.first().json;

let text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
text = text.replace(/[\x00-\x1F\x7F]/g, ' ');

let analysis;
try {
  analysis = JSON.parse(text);
} catch(e) {
  const m = text.match(/\{[\s\S]*\}/);
  try { analysis = m ? JSON.parse(m[0]) : {}; } catch(e2) { analysis = {}; }
}

const targetSegments = Math.max(4, Math.min(4, parseInt(analysis.recommended_segments) || 4));
const targetExtensions = targetSegments - 1;

const systemText = `You are an expert video prompt engineer for Google Veo 3.1. You have received a detailed cinematographic analysis of a reference video. Create exactly 4 prompts to recreate this video as a ~32-second generation (4 clips × 8 seconds each).\n\nINITIAL PROMPT (covers opening 8 seconds):\n- 150-250 words, single paragraph\n- Include: exact subject description (age, clothing, hair, expression), setting details, opening action, shot type and camera angle, lighting with color temperature, color palette with hex codes, texture details\n\nEXTENSION PROMPTS (3 prompts, each covers next 8 seconds):\n- 100-180 words each, single paragraph\n- Continue seamlessly from previous — same characters, same setting, same color palette\n- Describe progression of action, camera movement shifts, emotional development\n- Each must feel like a natural continuation\n\nRULES:\n1. ALL prompts share the same visual universe — consistent appearance, colors, lighting\n2. Focus on CORE ACTION: what the subject is actively DOING\n3. Use strong motion verbs: glides, reaches, turns, tilts, steps, applies, presses\n4. End EVERY prompt with: photorealistic, 4K resolution, cinematic lighting, 24fps, shallow depth of field\n5. NEVER include dialogue, voiceover, narration, sound descriptions — Veo generates audio automatically\n6. Never use negative phrasing (no X, without X)\n7. Output ONLY valid JSON, no markdown fences:\n{\n  "video_description": "2-3 sentence summary",\n  "core_action": "the main action being performed",\n  "initial_prompt": "detailed opening 8-second prompt...",\n  "extension_prompts": ["extension 1", "extension 2", "extension 3"]\n}`;

const userText = `Create 4 Veo 3.1 prompts based on this cinematographic analysis of the reference video:\n\n${JSON.stringify(analysis, null, 2)}\n\nTitle: ${srcData.title}\nAspect Ratio: ${srcData.aspect_ratio}\nFrames analyzed: ${srcData.frame_count}\n\nGenerate exactly 4 prompts (1 initial + 3 extensions) for a ~32-second video that faithfully recreates the reference.`;

const body = {
  contents: [{ role: 'user', parts: [{ text: userText }] }],
  systemInstruction: { parts: [{ text: systemText }] },
  generationConfig: { temperature: 0.3 }
};

return [{ json: {
  source_url: srcData.source_url,
  source_type: srcData.source_type,
  video_id: srcData.video_id,
  title: srcData.title,
  aspect_ratio: srcData.aspect_ratio,
  frame_count: srcData.frame_count,
  cinematography: analysis,
  target_segments: targetSegments,
  target_extensions: targetExtensions,
  target_duration: targetSegments * 8,
  gemini_body: JSON.stringify(body)
} }];

const srcData = $('Build Prompts Request').first().json;
const response = $input.first().json;

let text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
text = text.replace(/[\x00-\x1F\x7F]/g, ' ');

let parsed;
try {
  parsed = JSON.parse(text);
} catch(e) {
  const m = text.match(/\{[\s\S]*\}/);
  try { parsed = m ? JSON.parse(m[0]) : {}; } catch(e2) { parsed = {}; }
}

const initialPrompt = parsed.initial_prompt || 'A cinematic scene, photorealistic, 4K resolution, cinematic lighting, 24fps, shallow depth of field';
const extensionPrompts = parsed.extension_prompts || [];
const targetExt = srcData.target_extensions || 3;

// Pad extensions if Gemini returned fewer than requested
while (extensionPrompts.length < targetExt) {
  extensionPrompts.push(extensionPrompts[extensionPrompts.length - 1] || initialPrompt);
}

const allPrompts = [initialPrompt, ...extensionPrompts.slice(0, targetExt)];

return [{ json: {
  source_url: srcData.source_url,
  title: srcData.title,
  aspect_ratio: srcData.aspect_ratio,
  source_type: srcData.source_type,
  all_prompts: JSON.stringify(allPrompts),
  current_extension: 0,
  target_extensions: targetExt,
  video_base64: '',
  all_video_uris: '[]',
  video_description: parsed.video_description || '',
  poll_count: 0
} }];

const item = $input.first().json;
const currentExt = Number(item.current_extension) || 0;
const allPrompts = JSON.parse(item.all_prompts || '[]');
const prompt = allPrompts[currentExt] || 'A cinematic scene, photorealistic, 4K resolution, cinematic lighting, 24fps';
const aspectRatio = item.aspect_ratio || '16:9';
const videoBase64 = item.video_base64 || '';

// Use previous video for extension continuity (video-to-video mode)
const instances = [];
const instance = { prompt };
if (videoBase64 && currentExt > 0) {
  instance.video = { bytesBase64Encoded: videoBase64 };
}
instances.push(instance);

const requestBody = {
  instances,
  parameters: {
    aspectRatio,
    resolution: '720p',
    personGeneration: 'allow_all'
  }
};

return [{ json: {
  source_url: item.source_url || '',
  title: item.title || '',
  aspect_ratio: aspectRatio,
  source_type: item.source_type || 'youtube',
  all_prompts: item.all_prompts || '[]',
  current_extension: currentExt,
  target_extensions: item.target_extensions || 3,
  video_base64: '',
  all_video_uris: item.all_video_uris || '[]',
  video_description: item.video_description || '',
  veo_request_body: JSON.stringify(requestBody),
  current_prompt: prompt,
  poll_count: 0
} }];

const postResp = $input.first().json;
const buildData = $('Build Veo Request').first().json;
const opName = postResp.body?.name || postResp.name || '';
if (!opName) {
  throw new Error('Veo API error: ' + JSON.stringify(postResp.body || postResp).substring(0, 800));
}
return [{ json: {
  operation_name: opName,
  source_url: buildData.source_url || '',
  title: buildData.title || '',
  aspect_ratio: buildData.aspect_ratio || '16:9',
  source_type: buildData.source_type || 'youtube',
  all_prompts: buildData.all_prompts || '[]',
  current_extension: buildData.current_extension || 0,
  target_extensions: buildData.target_extensions || 5,
  all_video_uris: buildData.all_video_uris || '[]',
  video_description: buildData.video_description || '',
  current_prompt: buildData.current_prompt || '',
  poll_count: 0
} }];

const item = $input.first().json;
const capturedData = $('Track Poll Count').first().json;
const apiKey = 'AIzaSyAWWc4W-ZYeL6DF-8ZT6wXGPjh44vnO9SQ';

if (item.error) {
  return [{ json: {
    source_url: capturedData.source_url || '',
    title: capturedData.title || '',
    needs_extension: false,
    final_video_url: '',
    all_video_uris: capturedData.all_video_uris || '[]',
    error: item.error.message || JSON.stringify(item.error),
    status: 'failed',
    video_description: capturedData.video_description || '',
    current_prompt: capturedData.current_prompt || ''
  } }];
}

const samples = item.response?.generateVideoResponse?.generatedSamples || [];
const videoUri = samples[0]?.video?.uri || '';

if (!videoUri) {
  return [{ json: {
    source_url: capturedData.source_url || '',
    title: capturedData.title || '',
    needs_extension: false,
    final_video_url: '',
    all_video_uris: capturedData.all_video_uris || '[]',
    error: 'No video URI in response: ' + JSON.stringify(item).substring(0, 500),
    status: 'failed',
    video_description: capturedData.video_description || '',
    current_prompt: capturedData.current_prompt || ''
  } }];
}

const currentExt = capturedData.current_extension || 0;
const targetExt = capturedData.target_extensions || 5;
const existingUris = JSON.parse(capturedData.all_video_uris || '[]');
existingUris.push(videoUri);

const needsMore = currentExt < targetExt;

if (needsMore) {
  // Download the clip so we can use it as reference for video-to-video extension
  const videoResp = await this.helpers.httpRequest({
    method: 'GET',
    url: videoUri,
    encoding: 'arraybuffer',
    returnFullResponse: true,
    headers: { 'x-goog-api-key': apiKey }
  });
  const videoBase64 = Buffer.from(videoResp.body).toString('base64');

  return [{ json: {
    source_url: capturedData.source_url || '',
    title: capturedData.title || '',
    aspect_ratio: capturedData.aspect_ratio || '16:9',
    source_type: capturedData.source_type || 'youtube',
    all_prompts: capturedData.all_prompts || '[]',
    current_extension: currentExt + 1,
    target_extensions: targetExt,
    video_base64: videoBase64,
    all_video_uris: JSON.stringify(existingUris),
    video_description: capturedData.video_description || '',
    needs_extension: true,
    final_video_url: videoUri,
    error: '',
    status: 'extending_' + (currentExt + 1) + '_of_' + targetExt,
    poll_count: 0
  } }];
} else {
  return [{ json: {
    source_url: capturedData.source_url || '',
    title: capturedData.title || '',
    needs_extension: false,
    final_video_url: videoUri,
    all_video_uris: JSON.stringify(existingUris),
    error: '',
    status: 'completed',
    video_description: capturedData.video_description || '',
    current_prompt: capturedData.current_prompt || ''
  } }];
}

const d = $input.first().json;
const allUris = JSON.parse(d.all_video_uris || '[]');
const totalSeconds = allUris.length * 8;
return [{ json: {
  source_url: String(d.source_url || ''),
  video_title: String(d.title || ''),
  transcript: '',
  veo_prompt: String(d.current_prompt || d.video_description || ''),
  video_url: String(allUris.join(' | ') || ''),
  status: String(d.error ? 'failed' : 'completed_' + allUris.length + '_clips_' + totalSeconds + 's'),
  error: String(d.error || ''),
  completed_at: new Date().toISOString(),
  storyboard: String(d.video_description || '')
} }];

const d = $('Track Poll Count').first().json;
const allUris = JSON.parse(d.all_video_uris || '[]');
return [{ json: {
  source_url: String(d.source_url || ''),
  video_title: String(d.title || ''),
  transcript: '',
  veo_prompt: String(d.current_prompt || ''),
  video_url: allUris.length > 0 ? allUris.join(' | ') : '',
  status: 'timeout_ext_' + (d.current_extension || 0) + '_of_' + (d.target_extensions || 3),
  error: 'Timeout after 30 polls (~7.5 min). Partial: ' + allUris.length + ' clips.',
  completed_at: new Date().toISOString(),
  storyboard: ''
} }];
